int s_val = -1;
unsigned int u_val = 10;

// PITFALL: Signed operand promoted to unsigned (UINT_MAX)
// Comparison: UINT_MAX > 10 (TRUE)
if (s_val > u_val) {
    // Unexpected branch taken
}

// FIX 1: Cast the unsigned value down to signed
if (s_val > (int)u_val) {
    // Expected branch not taken
}

// FIX 2: Cast the signed value up to unsigned
if ((unsigned int)s_val > u_val) {
    // Equivalent to Pitfall check
}

// DIRECT CONVERSION RESULT
unsigned int promotion = s_val;
// promotion == UINT_MAX (or equivalent architecture max)

// PITFALL: Indexing arithmetic
size_t length = 5;
int idx = -1;

// idx promotes to UINT_MAX; length - idx causes wrap-around
size_t offset = length + idx; // 5 + UINT_MAX = 4 (Modulo arithmetic)
